import 'package:flutter/material.dart';
import '../core/theme/app_colors.dart';

class ChatScreen extends StatelessWidget { const ChatScreen({super.key}); @override Widget build(BuildContext context) => Scaffold(appBar: AppBar(title: const Text('Mensajes')), body: ListView(padding: const EdgeInsets.all(24), children: [const Text('PlastiPack Nicaragua', style: TextStyle(fontWeight: FontWeight.w800, fontSize: 18)), const SizedBox(height: 20), _bubble('Hola Carlos, recibimos tu solicitud para 2,000 unidades.', false), _bubble('Perfecto. ¿Pueden confirmar la fecha de entrega?', true), _bubble('Sí, podemos entregar en Managua en 4 días.', false), const SizedBox(height: 24), const TextField(decoration: InputDecoration(hintText: 'Escribe un mensaje', suffixIcon: Icon(Icons.send)))])); }
Widget _bubble(String text, bool mine) => Align(alignment: mine ? Alignment.centerRight : Alignment.centerLeft, child: Container(margin: const EdgeInsets.only(bottom: 10), padding: const EdgeInsets.all(14), constraints: const BoxConstraints(maxWidth: 420), decoration: BoxDecoration(color: mine ? AppColors.navy : AppColors.paleBlue, borderRadius: BorderRadius.circular(14)), child: Text(text, style: TextStyle(color: mine ? Colors.white : AppColors.textPrimary))));